<span class="line"><span class="__shiki_1t8gfj">sudo</span><span class="__shiki_mdbnqw"> cp</span><span class="__shiki_mdbnqw"> application-prod.yml</span><span class="__shiki_mdbnqw"> /opt/myapp/config/</span></span>
